import{_ as e,c as s,o as a,ag as d}from"./chunks/framework._xRlcm3f.js";const i="/siyuan-plugin-publisher/images/shots/path-vitepress.webp",b=JSON.parse('{"title":"Vitepress 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/github-vitepress.md","filePath":"platforms/github-vitepress.md","lastUpdated":1790228279000}'),o={name:"platforms/github-vitepress.md"};function r(l,t,n,c,p,h){return a(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="vitepress-配置指南" tabindex="-1">Vitepress 配置指南 <a class="header-anchor" href="#vitepress-配置指南" aria-label="Permalink to &quot;Vitepress 配置指南&quot;">​</a></h1><p>通过 <strong>GitHub API</strong> 将文章发布到 <strong>Vitepress</strong> 文档站仓库。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可作为 Vitepress 站点的 <strong>GitHub 仓库</strong>（如 <code>vitepress-blog</code>，文档文章放在 <code>docs</code> 下）。</li><li>一个对该仓库有 <strong>push 权限</strong> 的 <strong>GitHub Token（PAT）</strong>（GitHub Settings → Developer settings → Personal access tokens，勾选 <code>repo</code> 权限）。</li><li>站点仓库已配置构建部署（例如 Vercel / GitHub Actions / Netlify），推送 <code>.md</code> 后能触发重新构建上线。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>首页地址</td><td>GitHub 首页地址，默认 <code>https://github.com</code></td></tr><tr><td>API 地址</td><td>GitHub API 地址，默认 <code>https://api.github.com</code>，通常无需修改</td></tr><tr><td>用户名</td><td>GitHub 用户名（owner），用于拼出仓库地址</td></tr><tr><td>鉴权 Token</td><td>GitHub 个人访问令牌（PAT），需对目标仓库有 push 权限</td></tr><tr><td>git 仓库名</td><td>站点仓库名（裸仓库名，不带 <code>owner/</code> 前缀），例如 <code>vitepress-blog</code></td></tr><tr><td>默认分支</td><td>发布到的分支，默认 <code>main</code></td></tr><tr><td>存储目录</td><td>文章存储目录，默认 <code>docs</code>。发布后的 <code>.md</code> 会写入该目录</td></tr><tr><td>文件规则</td><td>文章文件名规则，默认 <code>[slug].md</code>（文章别名）</td></tr><tr><td>文章预览规则</td><td>站点文章预览规则，默认 <code>/post/[postid].html</code>（Vitepress 采用基于文件路径的路由，实际地址由文件路径决定，此规则仅作查看参考）</td></tr><tr><td>预览规则</td><td>GitHub blob 预览规则，默认 <code>/[user]/[repo]/blob/[branch]/[docpath]</code></td></tr><tr><td>图床</td><td>选「当前平台」：图片上传到<strong>文章所在目录</strong>的 <code>images</code> 子目录（规则 <code>[docpath]/images</code>，如 <code>docs/images/&lt;图片名&gt;</code>），文章引用相对路径 <code>./images/&lt;图片名&gt;</code></td></tr></tbody></table><p>发布写入的 front matter 含 <code>title</code>、<code>date</code>、<code>description</code>、<code>categories</code>，并在 <code>head</code> 中按需写入 <code>keywords</code> / <code>description</code>（可在「YAML 预设配置」中覆盖）。</p><h2 id="三、yaml-预设配置的默认行为" tabindex="-1">三、YAML 预设配置的默认行为 <a class="header-anchor" href="#三、yaml-预设配置的默认行为" aria-label="Permalink to &quot;三、YAML 预设配置的默认行为&quot;">​</a></h2><p>「YAML 预设配置」留空时，Vitepress 平台会写入以下默认值：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">outline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deep</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">sidebar</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">prev</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">next</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>填入 JSON 片段（例如 <code>{&quot;sidebar&quot;: true}</code>）时，改为逐键合并进 Front Matter。</p><h2 id="四、图片约定" tabindex="-1">四、图片约定 <a class="header-anchor" href="#四、图片约定" aria-label="Permalink to &quot;四、图片约定&quot;">​</a></h2><ul><li><code>imageStorePath = [docpath]/images</code> 会解析为文章所在目录下的 <code>images/</code> 子目录（例如 <code>docs/images/&lt;图片名&gt;</code>）。</li><li>文章内引用 <code>imageLinkPath = ./images</code> 生成<strong>相对路径</strong> <code>./images/&lt;图片名&gt;</code>，随页面一起输出。</li><li>因此选「当前平台」图床发布带图文章后，仓库中会同时出现 <code>.md</code> 与同目录 <code>images/&lt;图片名&gt;</code>。</li></ul><h2 id="五、验证与发布" tabindex="-1">五、验证与发布 <a class="header-anchor" href="#五、验证与发布" aria-label="Permalink to &quot;五、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ Token、仓库、分支校验通过 → 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 Vitepress → 发布。文章 <code>.md</code> 提交到 <code>存储目录/[slug].md</code>。</li><li>「查看文章」打开仓库 blob 地址；站点线上地址由文件路径决定，需站点已构建部署。</li><li>带图发布时图片上传到文章所在目录的 <code>images/</code>，文章引用 <code>./images/&lt;图片名&gt;</code>。</li></ol><h2 id="图片存储路径" tabindex="-1">图片存储路径 <a class="header-anchor" href="#图片存储路径" aria-label="Permalink to &quot;图片存储路径&quot;">​</a></h2><p>图床选「当前平台」时，可以指定图片存到仓库哪里：</p><p><img src="`+i+'" alt="填写图片存储目录与访问链接" loading="lazy"></p><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th></tr></thead><tbody><tr><td>图片存储目录</td><td><code>[docpath]/images</code></td></tr><tr><td>图片访问链接</td><td><code>./images</code></td></tr></tbody></table><p>VitePress 推荐用<strong>相对路径</strong>引用图片，因此链接写 <code>./images</code>。一般不需要改，改了请保证两个值<strong>对应</strong>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证通过但发布失败</strong>：确认 Token 对目标仓库有 push 权限、仓库名与分支正确。权限不足会收到 401/403。</li><li><strong>图片要怎么发布</strong>：选「当前平台」图床，图片上传到文章所在目录的 <code>images/</code> 子目录，文章引用相对路径 <code>./images/&lt;图片名&gt;</code>。</li><li><strong>线上没有新文章</strong>：Vitepress 站点需要构建。确认仓库已绑定 Vercel / Actions 等自动构建；仅推送 <code>.md</code> 不会直接改变已部署站点。</li><li><strong>更新与删除</strong>：点「更新」会重新提交该文章并产生一次新提交；「删除」会移除仓库中对应的 <code>.md</code>，站点需重新构建才会同步下线。</li></ul>',22)])])}const m=e(o,[["render",r]]);export{b as __pageData,m as default};
